# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HUDEYBİYE ANTLAŞMASI\'NIN BOZULMASI VE FETİH SEBEPLERİ</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Hudeybiye Antlaşması (628 / Hicri 6)</text>\n  <text x="40" y="98" font-size="11.5" fill="#334155">• Müslümanlar ile Mekkeli müşrikler arasında</text>\n  <text x="48" y="115" font-size="11.5" fill="#334155"><tspan font-weight="bold">10 yıl süreli</tspan> barış antlaşması imzalandı.</text>\n  <text x="40" y="140" font-size="11.5" fill="#334155">• Arap kabileleri dilediği tarafın ittifakına</text>\n  <text x="48" y="157" font-size="11.5" fill="#334155">girmekte serbest bırakıldı:</text>\n  <text x="48" y="182" font-size="11.5" font-weight="bold" fill="#15803d">✓ Huzaa Kabilesi → Hz. Peygamber\'in himayesi</text>\n  <text x="48" y="206" font-size="11.5" font-weight="bold" fill="#b91c1c">✗ Bekiroğulları (Benî Bekir) → Kureyş ittifakı</text>\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Antlaşmanın İhlali (630 / Hicri 8)</text>\n  <text x="375" y="98" font-size="11.5" fill="#334155">• Bekiroğulları, Mekkeli müşriklerden silah ve</text>\n  <text x="383" y="115" font-size="11.5" fill="#334155">asker desteği alarak <tspan font-weight="bold">Huzaa kabilesine</tspan> saldırdı.</text>\n  <text x="375" y="140" font-size="11.5" fill="#334155">• Kâbe\'nin Harem bölgesinde bile Huzaalılar</text>\n  <text x="383" y="157" font-size="11.5" fill="#334155">şehit edildi ve ahde vefa ilkesi çiğnendi.</text>\n  <text x="375" y="182" font-size="11.5" fill="#334155">• Hz. Peygamber\'in barışçıl çözüm şartlarını</text>\n  <text x="383" y="199" font-size="11.5" fill="#334155">reddeden müşrikler antlaşmayı bozmayı seçti.</text>\n  <text x="375" y="222" font-size="11" font-weight="bold" fill="#991b1b">→ Mazlum Huzaa kabilesini korumak için sefer başladı.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MEKKE\'NİN FETHİ SÜRECİ VE BARIŞÇIL STRATEJİ (OCAK 630)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Gizlilik ve Merru\'z-Zahrân</text>\n  <text x="32" y="98" font-size="11" fill="#334155">• Kan dökülmesini önlemek için</text>\n  <text x="40" y="114" font-size="11" fill="#334155">hazırlık gizli tutuldu.</text>\n  <text x="32" y="138" font-size="11" fill="#334155">• <tspan font-weight="bold">10.000 kişilik</tspan> İslam ordusu</text>\n  <text x="40" y="154" font-size="11" fill="#334155">Merru\'z-Zahrân\'da konakladı.</text>\n  <text x="32" y="178" font-size="11" fill="#334155">• Direnişi kırmak için her askere</text>\n  <text x="40" y="194" font-size="11" font-weight="bold" fill="#1e3a8a">bir ateş yaktırıldı.</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Eman (Güvence) İlanı</text>\n  <text x="257" y="98" font-size="11" fill="#334155">• Ebû Süfyan İslam\'ı kabul etti.</text>\n  <text x="257" y="122" font-size="11" font-weight="bold" fill="#14532d">Güvence (Eman) Verilenler:</text>\n  <text x="262" y="144" font-size="10.5" fill="#334155">1. Kâbe\'ye (Mescid-i Haram\'a)</text>\n  <text x="272" y="160" font-size="10.5" fill="#334155">sığınanlar</text>\n  <text x="262" y="180" font-size="10.5" fill="#334155">2. Silah bırakıp evine kapananlar</text>\n  <text x="262" y="200" font-size="10.5" fill="#334155">3. Ebû Süfyan\'ın evine girenler</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. Tevazu İle Şehre Giriş</text>\n  <text x="482" y="98" font-size="11" fill="#334155">• Ordu 4 koldan şehre girdi;</text>\n  <text x="490" y="114" font-size="11" fill="#334155">mecbur kalmadıkça silah</text>\n  <text x="490" y="130" font-size="11" fill="#334155">kullanılmaması emredildi.</text>\n  <text x="482" y="156" font-size="11" fill="#334155">• Peygamberimiz devesi Kasvâ</text>\n  <text x="490" y="172" font-size="11" fill="#334155">üzerinde şükür ve tevazuyla</text>\n  <text x="490" y="188" font-size="11" font-weight="bold" fill="#854d0e">Fetih Suresi\'ni okuyarak</text>\n  <text x="490" y="204" font-size="11" fill="#334155">Mekke\'ye girdi.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KÂBE\'NİN PUTLARDAN TEMİZLENMESİ, GENEL AF VE FETHİN SONUÇLARI</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Tevhid Sembolü ve Genel Af</text>\n  <text x="40" y="98" font-size="11.5" fill="#334155">• <tspan font-weight="bold">İsrâ Suresi 81. ayet:</tspan> "De ki: Hak geldi,</text>\n  <text x="48" y="115" font-size="11.5" fill="#334155">batıl yıkılıp gitti..." okunarak Kâbe</text>\n  <text x="48" y="132" font-size="11.5" font-weight="bold" fill="#9d174d">360 puttan tamamen temizlendi.</text>\n  <text x="40" y="156" font-size="11.5" fill="#334155">• Hz. Bilâl-i Habeşî Kâbe\'nin damında ezan okudu.</text>\n  <text x="40" y="180" font-size="11.5" fill="#334155">• <tspan font-weight="bold">Genel Af (Yûsuf Suresi, 92):</tspan></text>\n  <text x="48" y="198" font-size="11.5" font-weight="bold" fill="#831843">"Bugün size kınama yoktur, hepiniz</text>\n  <text x="48" y="215" font-size="11.5" font-weight="bold" fill="#831843">serbestsiniz!" buyrularak gönüller fethedildi.</text>\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Mekke\'nin Fethinin Sonuçları</text>\n  <text x="375" y="100" font-size="11.5" fill="#334155">1. Kâbe putlardan arındırılarak yeniden</text>\n  <text x="387" y="117" font-size="11.5" font-weight="bold" fill="#14532d">tevhid inancının merkezi oldu.</text>\n  <text x="375" y="142" font-size="11.5" fill="#334155">2. Mekkeli müşriklerin 20 yıllık baskı ve</text>\n  <text x="387" y="159" font-size="11.5" fill="#334155">düşmanlığı kesin olarak sona erdi.</text>\n  <text x="375" y="184" font-size="11.5" fill="#334155">3. İntikam yerine merhamet gösterilmesiyle</text>\n  <text x="387" y="201" font-size="11.5" fill="#334155">Mekkeliler kitleler halinde Müslüman oldu.</text>\n  <text x="375" y="224" font-size="11.5" fill="#334155">4. Arap Yarımadası\'nda İslam hızla yayıldı.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
